insert into public.services (id, category_id, slug, name, description, price_cents, price_from, unit, duration_min, is_small, is_addon, is_active, sort) values
  (1, 1, 'armchair', '{"fi":"Nojatuoli","ru":"Кресло","en":"Armchair"}'::jsonb, '{"fi":"Nojatuoli tai korvanojatuoli, kaikki pinnat.","ru":"Кресло, в том числе «с ушами», все поверхности.","en":"Armchair or wingback, all surfaces."}'::jsonb, 5000, false, 'item', 40, true, false, true, 10),
  (2, 1, 'sofa-2', '{"fi":"2-istuttava sohva","ru":"2-местный диван","en":"2-seater sofa"}'::jsonb, '{"fi":"Istuintyynyt, selkänoja ja käsinojat.","ru":"Сиденья, спинка и подлокотники.","en":"Seat cushions, backrest and armrests."}'::jsonb, 10900, false, 'item', 45, false, false, true, 20),
  (3, 1, 'sofa-3', '{"fi":"3-istuttava sohva","ru":"3-местный диван","en":"3-seater sofa"}'::jsonb, '{"fi":"Yleisin sohvakoko, kaikki pinnat höyryllä.","ru":"Самый частый размер, все поверхности с паром.","en":"The most common size, all surfaces steam-cleaned."}'::jsonb, 14900, false, 'item', 60, false, false, true, 30),
  (4, 1, 'sofa-4', '{"fi":"4-istuttava sohva","ru":"4-местный диван","en":"4-seater sofa"}'::jsonb, '{"fi":"Suora 4-istuttava tai divaanisohva.","ru":"Прямой 4-местный диван или диван с оттоманкой.","en":"Straight 4-seater or chaise sofa."}'::jsonb, 16900, false, 'item', 120, false, false, true, 40),
  (5, 1, 'corner', '{"fi":"Kulmasohva","ru":"Угловой диван","en":"Corner sofa"}'::jsonb, '{"fi":"Tavallinen L-mallinen kulmasohva.","ru":"Обычный угловой диван Г-образной формы.","en":"Standard L-shaped corner sofa."}'::jsonb, 16900, false, 'item', 90, false, false, true, 50),
  (6, 1, 'corner-large', '{"fi":"Iso kulmasohva","ru":"Большой угловой диван","en":"Large corner sofa"}'::jsonb, '{"fi":"U-mallinen tai yli 3 metrin kulmasohva.","ru":"П-образный или угловой диван длиннее 3 метров.","en":"U-shaped or over 3 m corner sofa."}'::jsonb, 19900, false, 'item', 120, false, false, true, 60),
  (7, 1, 'sofa-5-6', '{"fi":"5–6-istuttava sohva","ru":"5–6-местный диван","en":"5–6-seater sofa"}'::jsonb, '{"fi":"Suuri moduulisohva tai kahden sohvan kokonaisuus.","ru":"Большой модульный диван.","en":"Large modular sofa."}'::jsonb, 19900, false, 'item', 120, false, false, true, 70),
  (8, 1, 'ottoman-s', '{"fi":"Rahi (pieni)","ru":"Пуф (маленький)","en":"Ottoman (small)"}'::jsonb, '{"fi":"Pieni rahi tai jalkatuki.","ru":"Небольшой пуф или подставка для ног.","en":"Small ottoman or footstool."}'::jsonb, 2500, false, 'item', 10, true, false, true, 80),
  (9, 1, 'ottoman-l', '{"fi":"Rahi (iso)","ru":"Пуф (большой)","en":"Ottoman (large)"}'::jsonb, '{"fi":"Iso rahi tai sohvan erillinen moduuli.","ru":"Большой пуф или отдельный модуль дивана.","en":"Large ottoman or a separate sofa module."}'::jsonb, 4000, false, 'item', 15, true, false, true, 90),
  (10, 2, 'leather-armchair', '{"fi":"Nahkanojatuoli","ru":"Кожаное кресло","en":"Leather armchair"}'::jsonb, '{"fi":"Puhdistus nahalle tarkoitetulla aineella käsin.","ru":"Ручная чистка средством для кожи.","en":"Hand-cleaned with a leather-safe product."}'::jsonb, 5000, false, 'item', 40, true, false, true, 100),
  (11, 2, 'leather-sofa-2', '{"fi":"2-istuttava nahkasohva","ru":"2-местный кожаный диван","en":"2-seater leather sofa"}'::jsonb, '{"fi":"Puhdistus ja pintalian poisto, sopii aidolle ja keinonahalle.","ru":"Чистка и снятие поверхностной грязи, для натуральной и искусственной кожи.","en":"Cleaning and soil removal for genuine and faux leather."}'::jsonb, 10900, false, 'item', 50, false, false, true, 110),
  (12, 2, 'leather-sofa-3', '{"fi":"3-istuttava nahkasohva","ru":"3-местный кожаный диван","en":"3-seater leather sofa"}'::jsonb, '{"fi":"Puhdistus saumoja ja taitteita myöten.","ru":"Чистка, включая швы и складки.","en":"Cleaning including seams and creases."}'::jsonb, 14900, false, 'item', 70, false, false, true, 120),
  (13, 2, 'leather-corner', '{"fi":"Nahkakulmasohva","ru":"Кожаный угловой диван","en":"Leather corner sofa"}'::jsonb, '{"fi":"Kulmasohva tai 4-istuttava nahkasohva.","ru":"Угловой или 4-местный кожаный диван.","en":"Corner or 4-seater leather sofa."}'::jsonb, 16900, false, 'item', 100, false, false, true, 130),
  (14, 3, 'chair-seat', '{"fi":"Ruokapöydän tuoli, istuin","ru":"Обеденный стул, сиденье","en":"Dining chair, seat"}'::jsonb, '{"fi":"Pelkkä istuinosa, hinta kappaleelta.","ru":"Только сиденье, цена за штуку.","en":"Seat only, price per chair."}'::jsonb, 1400, false, 'piece', 10, true, false, true, 140),
  (15, 3, 'chair-full', '{"fi":"Ruokapöydän tuoli, selkänoja ja istuin","ru":"Обеденный стул, спинка и сиденье","en":"Dining chair, backrest and seat"}'::jsonb, '{"fi":"Verhoiltu istuin ja selkänoja, hinta kappaleelta.","ru":"Мягкие сиденье и спинка, цена за штуку.","en":"Upholstered seat and backrest, price per chair."}'::jsonb, 2000, false, 'piece', 15, true, false, true, 150),
  (16, 3, 'office-chair', '{"fi":"Työtuoli","ru":"Офисное кресло","en":"Office chair"}'::jsonb, '{"fi":"Työtuolin istuin, selkänoja ja käsinojat.","ru":"Сиденье, спинка и подлокотники офисного кресла.","en":"Seat, backrest and armrests of an office chair."}'::jsonb, 4000, false, 'piece', 20, true, false, true, 160),
  (17, 4, 'bed-single', '{"fi":"Yhden hengen sänky / patja","ru":"Односпальная кровать / матрас","en":"Single bed / mattress"}'::jsonb, '{"fi":"80–120 cm leveä patja, molemmat puolet tarvittaessa.","ru":"Матрас шириной 80–120 см, при необходимости с двух сторон.","en":"80–120 cm wide mattress, both sides when needed."}'::jsonb, 9900, false, 'item', 60, false, false, true, 170),
  (18, 4, 'bed-double', '{"fi":"Parisänky / patja","ru":"Двуспальная кровать / матрас","en":"Double bed / mattress"}'::jsonb, '{"fi":"140–180 cm leveä patja tai runkopatjat ja sijauspatja.","ru":"Матрас шириной 140–180 см или матрасы с наматрасником.","en":"140–180 cm wide mattress or box springs with a topper."}'::jsonb, 16000, false, 'item', 90, false, false, true, 180),
  (19, 5, 'odor-removal', '{"fi":"Hajunpoisto pesun yhteydessä","ru":"Удаление запахов во время чистки","en":"Odor removal with cleaning"}'::jsonb, '{"fi":"Sisältyy pesun hintaan — kerro hajusta varauksen yhteydessä.","ru":"Входит в цену чистки — сообщите о запахе при записи.","en":"Included in the cleaning price — mention the odor when booking."}'::jsonb, 0, false, 'item', 0, true, true, true, 190),
  (20, 6, 'car-5', '{"fi":"Henkilöauto, 5 paikkaa","ru":"Легковой автомобиль, 5 мест","en":"Car, 5 seats"}'::jsonb, '{"fi":"Penkit, matot ja oviverhoilut.","ru":"Сиденья, коврики и обивка дверей.","en":"Seats, floor mats and door upholstery."}'::jsonb, 17900, false, 'item', 150, false, false, true, 200),
  (21, 6, 'car-seat', '{"fi":"Yksittäinen istuin","ru":"Одно сиденье","en":"Single seat"}'::jsonb, '{"fi":"Yksi auton istuin.","ru":"Одно автомобильное сиденье.","en":"One car seat."}'::jsonb, 4000, false, 'piece', 20, true, false, true, 210),
  (22, 6, 'camper', '{"fi":"Asuntoauton tai -vaunun penkit","ru":"Сиденья автодома или жилого прицепа","en":"Motorhome or caravan seats"}'::jsonb, '{"fi":"Hinta penkkien määrän mukaan.","ru":"Цена зависит от количества сидений.","en":"Priced by the number of seats."}'::jsonb, 14900, true, 'item', 180, false, false, true, 220),
  (23, 7, 'boat-textiles', '{"fi":"Veneen tekstiilit","ru":"Текстиль лодки или катера","en":"Boat textiles"}'::jsonb, '{"fi":"Patjat ja istuintyynyt, hinta veneen koon mukaan.","ru":"Матрасы и подушки сидений, цена зависит от размера лодки.","en":"Mattresses and seat cushions, priced by boat size."}'::jsonb, 10000, true, 'item', 120, false, false, true, 230),
  (24, 8, 'stroller', '{"fi":"Lastenvaunut, rattaat tai turvaistuin","ru":"Детская коляска или автокресло","en":"Stroller or child car seat"}'::jsonb, '{"fi":"Kangasosat höyryllä ja allergiaystävällisellä aineella.","ru":"Тканевые части паром и гипоаллергенным средством.","en":"Fabric parts with steam and an allergy-friendly product."}'::jsonb, 2500, true, 'item', 30, true, false, true, 240),
  (25, 8, 'soft-toy', '{"fi":"Isot pehmolelut","ru":"Большие мягкие игрушки","en":"Large soft toys"}'::jsonb, '{"fi":"Isot pehmolelut, jotka eivät mahdu pesukoneeseen.","ru":"Большие игрушки, которые не помещаются в стиральную машину.","en":"Large soft toys that do not fit in a washing machine."}'::jsonb, 2000, true, 'item', 15, true, false, true, 250),
  (26, 9, 'b2b-office-chair', '{"fi":"Työtuoli (yrityksille)","ru":"Офисное кресло (для компаний)","en":"Office chair (business)"}'::jsonb, '{"fi":"Yrityshinta kappaleelta, laskulla.","ru":"Цена для компаний за штуку, по счёту.","en":"Business price per chair, by invoice."}'::jsonb, 3400, false, 'piece', 20, true, true, true, 260),
  (27, 9, 'b2b-dining-chair', '{"fi":"Ravintolatuoli, selkänoja ja istuin","ru":"Стул для ресторана, спинка и сиденье","en":"Restaurant chair, backrest and seat"}'::jsonb, '{"fi":"Ravintolat, kahvilat ja neuvotteluhuoneet.","ru":"Рестораны, кафе и переговорные.","en":"Restaurants, cafés and meeting rooms."}'::jsonb, 2100, false, 'piece', 15, true, true, true, 270),
  (28, 9, 'b2b-lobby-sofa', '{"fi":"Toimisto- tai aulasohva","ru":"Офисный диван или диван в лобби","en":"Office or lobby sofa"}'::jsonb, '{"fi":"Hinta koon mukaan, kuten sohvien hinnastossa.","ru":"Цена по размеру, как в прайсе на диваны.","en":"Priced by size, as in the sofa price list."}'::jsonb, 5000, true, 'item', 60, true, true, true, 280)
